'use strict';

// MODULES //

var floorf = require( '@stdlib/math/base/special/floorf' );


// MAIN //

/**
* Rounds each component of a single-precision complex floating-point number toward negative infinity and assigns results to a provided output array.
*
* @param {number} re - real component
* @param {number} im - imaginary component
* @param {Collection} out - output array
* @param {integer} strideOut - stride length
* @param {NonNegativeInteger} offsetOut - starting index
* @returns {Collection} output array
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var out = assign( -1.5, 2.5, new Float32Array( 2 ), 1, 0 );
* // returns <Float32Array>[ -2.0, 2.0 ]
*/
function assign( re, im, out, strideOut, offsetOut ) {
	out[ offsetOut ] = floorf( re );
	out[ offsetOut+strideOut ] = floorf( im );
	return out;
}


// EXPORTS //

module.exports = assign;
